    RQRCode::QRCode.new(url).as_svg(offset: 0, color: "#0d0640", shape_rendering: "crispEdges", module_size: 5, use_path: true)
  end

  def option_letter(index)
    number = index + 1
    letters = String.new

    while number.positive?
      number, remainder = (number - 1).divmod(26)
      letters.prepend((65 + remainder).chr)
    end

    letters
  end
